/* 학습 해설
 * OF 주소entry 조회·index와PCI BAR
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * parentbus를선택해reg또는assigned-addresses를읽습니다. BAR요청은PCI가아니면NULL이고주소cellcount를검사합니다. entry마다firstword낮은8bit를BARregister번호와비교하거나일반index를비교합니다. 반환은원본propertycursor이며새복사본이아닙니다.
 * index번째reg와BAR번호선택을별도표로적습니다. na+ns완전entry반복과선택size/flagsoutput,주소cell과sizecell의검사차이를확인합니다.
 */
const __be32 *__of_get_address(struct device_node *dev, int index, int bar_no,
			       u64 *size, unsigned int *flags)
{
	const __be32 *prop;
	unsigned int psize;
	struct device_node *parent __free(device_node) = of_get_parent(dev);
	struct of_bus *bus;
	int onesize, i, na, ns;

	if (parent == NULL)
		return NULL;

	/* match the parent's bus type */
	bus = of_match_bus(parent);
	if (strcmp(bus->name, "pci") && (bar_no >= 0))
		return NULL;

	bus->count_cells(dev, &na, &ns);
	if (!OF_CHECK_ADDR_COUNT(na))
		return NULL;

	/* Get "reg" or "assigned-addresses" property */
	prop = of_get_property(dev, bus->addresses, &psize);
	if (prop == NULL)
		return NULL;
	psize /= 4;

/* 학습 해설
 * OF untranslated reg읽기·물리변환과구별
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * of_get_address로entry를얻고없으면EINVAL입니다. 정상은of_n_addr_cells로숫자를읽어*addr에넣고0입니다. 이름처럼ranges를따라CPU물리주소로변환하는API가아니며addroutput유효성은caller의계약입니다.
 * 버스local0x1020과변환뒤CPU0x8020을두값으로적습니다. propertyread와of_address_to_resource의호출흐름차이를확인합니다.
 */
int of_property_read_reg(struct device_node *np, int idx, u64 *addr, u64 *size)
{
	const __be32 *prop = of_get_address(np, idx, size, NULL);

	if (!prop)
		return -EINVAL;

	*addr = of_read_number(prop, of_n_addr_cells(np));

	return 0;
}
EXPORT_SYMBOL(of_property_read_reg);

static int parser_init(struct of_pci_range_parser *parser,
			struct device_node *node, const char *name)
{
	int rlen;

	parser->node = node;
	parser->pna = of_n_addr_cells(node);
	parser->na = of_bus_n_addr_cells(node);
	parser->ns = of_bus_n_size_cells(node);
	parser->dma = !strcmp(name, "dma-ranges");
	parser->bus = of_match_bus(node);

	parser->range = of_get_property(node, name, &rlen);

/* 학습 해설
 * OF range parser준비·주소폭과끝pointer
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * node와parentaddress폭pna,busaddressna,size폭ns,dma여부/bus를저장합니다. property부재는ENOENT,정상end는range+byte길이/4입니다. 여기서모든cellcount/남은byte나머지를독립검사하지않으며iterator의완전entry조건과함께읽습니다.
 * range배열시작/끝과na+pna+ns를그립니다. ranges와dma-rangeswrapper가같은init에이름만전달하는재사용을주석달아봅니다.
 */
static int parser_init(struct of_pci_range_parser *parser,
			struct device_node *node, const char *name)
{
	int rlen;

	parser->node = node;
	parser->pna = of_n_addr_cells(node);
	parser->na = of_bus_n_addr_cells(node);
	parser->ns = of_bus_n_size_cells(node);
	parser->dma = !strcmp(name, "dma-ranges");
	parser->bus = of_match_bus(node);

	parser->range = of_get_property(node, name, &rlen);
	if (parser->range == NULL)
		return -ENOENT;

	parser->end = parser->range + rlen / sizeof(__be32);

	return 0;
}

int of_pci_range_parser_init(struct of_pci_range_parser *parser,
				struct device_node *node)
{
	return parser_init(parser, node, "ranges");
}

/* 학습 해설
 * OF range parser한entry·주소변환과size
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * outputNULL/range없음/완전entry부재는NULL입니다. flags와bus_addr를읽고parent주소를일반또는DMA변환해cpu_addr를얻고size를읽습니다. parsercursor는다음entry로전진합니다. CPU변환BAD도이본문이항상즉시NULL로거부하지않아caller가cpu_addr를확인합니다.
 * child주소/parent주소/size의entry배치를그립니다. cursor소비와outputfields,변환status표현을분리해뒤DMAmap의BADskip정책과연결합니다.
 */
struct of_pci_range *of_pci_range_parser_one(struct of_pci_range_parser *parser,
						struct of_pci_range *range)
{
	int na = parser->na;
	int ns = parser->ns;
	int np = parser->pna + na + ns;
	int busflag_na = parser->bus->flag_cells;

	if (!range)
		return NULL;

	if (!parser->range || parser->range + np > parser->end)
		return NULL;

	range->flags = parser->bus->get_flags(parser->range);

	range->bus_addr = of_read_number(parser->range + busflag_na, na - busflag_na);

	if (parser->dma)
		range->cpu_addr = of_translate_dma_address(parser->node,
				parser->range + na);
	else
		range->cpu_addr = of_translate_address(parser->node,
				parser->range + na);
	range->size = of_read_number(parser->range + parser->pna + na, ns);

/* 학습 해설
 * OF 연속range합치기·두주소와동일flags
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * 뒤entryflags가같고bus_addr와cpu_addr둘다가기존start+size에이어질때size를더하고cursor를계속소비합니다. 한쪽주소만연속이면합치지않습니다. size/끝합의모든overflow를본문이별도검사하는것은아닙니다.
 * bus0x1000→0x1100/cpu0x8000→0x8100/size0x100두entry가0x200이되는계산을풉니다. flags/CPU연속조건이깨지면뒤entry를남기는이유를적습니다.
 */
struct of_pci_range *of_pci_range_parser_one(struct of_pci_range_parser *parser,
						struct of_pci_range *range)
{
	int na = parser->na;
	int ns = parser->ns;
	int np = parser->pna + na + ns;
	int busflag_na = parser->bus->flag_cells;

	if (!range)
		return NULL;

	if (!parser->range || parser->range + np > parser->end)
		return NULL;

	range->flags = parser->bus->get_flags(parser->range);

	range->bus_addr = of_read_number(parser->range + busflag_na, na - busflag_na);

	if (parser->dma)
		range->cpu_addr = of_translate_dma_address(parser->node,
				parser->range + na);
	else
		range->cpu_addr = of_translate_address(parser->node,
				parser->range + na);
	range->size = of_read_number(parser->range + parser->pna + na, ns);

/* 학습 해설
 * OF IOport변환·host와memory-mapped경로
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * 공통translation의host가있으면logic_pio_trans_hwaddr로host상대값을port로바꾸고put합니다. host가없으면pci_address_to_pio를씁니다. port-1은BAD입니다. host/MMIO의두경로와실제port접근이분리됩니다.
 * indirectIOhost와CPU_MMIO물리범위의두변환을그립니다. token을일반Cpointer로임의역참조하지않고platformIO접근계약을따로확인합니다.
 */
static u64 of_translate_ioport(struct device_node *dev, const __be32 *in_addr,
			u64 size)
{
	u64 taddr;
	unsigned long port;
	struct device_node *host;

	taddr = __of_translate_address(dev, of_get_parent,
				       in_addr, "ranges", &host);
	if (host) {
		/* host-specific port access */
		port = logic_pio_trans_hwaddr(&host->fwnode, taddr, size);
		of_node_put(host);
	} else {
		/* memory-mapped I/O range */
		port = pci_address_to_pio(taddr);
	}

	if (port == (unsigned long)-1)
		return OF_BAD_ADDR;

	return port;
}

#ifdef CONFIG_HAS_DMA
/**
 * of_dma_get_range - Get DMA range info and put it into a map array
 * @np:		device node to get DMA range info
 * @map:	dma range structure to return
 *
 * Look in bottom up direction for the first "dma-ranges" property
 * and parse it.  Put the information into a DMA offset map array.
 *
 * dma-ranges format:
 *	DMA addr (dma_addr)	: naddr cells
 *	CPU addr (phys_addr_t)	: pna cells
 *	size			: nsize cells
 *
 * It returns -ENODEV if "dma-ranges" property was not found for this
 * device in the DT.
 */

/* 학습 해설
 * OF DMA range탐색·empty와부재정책
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * DMAparent를올라가첫nonemptydma-ranges를찾습니다. empty는translation불필요로넘기지만found상태뒤missing이면ENODEV입니다. 코드의foundflag대입시점과특수DMAparent관계를읽고모든missingancestor를언제나허용한다고단정하지않습니다.
 * 현재node부재/empty,parentnonempty,parentmissing의경로를그립니다. 함수주석과실제foundflag조건을나눠읽고원문callbackparent의참조수명을연결합니다.
 */
int of_dma_get_range(struct device_node *np, const struct bus_dma_region **map)
{
	struct device_node *node __free(device_node) = of_node_get(np);
	const __be32 *ranges = NULL;
	bool found_dma_ranges = false;
	struct of_range_parser parser;
	struct of_range range;
	struct bus_dma_region *r;
	int len, num_ranges = 0;

	while (node) {
		ranges = of_get_property(node, "dma-ranges", &len);

		/* Ignore empty ranges, they imply no translation required */
		if (ranges && len > 0)
			break;

		/* Once we find 'dma-ranges', then a missing one is an error */
		if (found_dma_ranges && !ranges)
			return -ENODEV;

		found_dma_ranges = true;

		node = of_get_next_dma_parent(node);
	}

/* 학습 해설
 * OF DMA map배열·두pass와zero sentinel
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * parser첫pass에서cpu_addr가BAD인range를넘겨유효개수를셉니다. 없으면EINVAL입니다. num+1개를kcalloc해0sentinel을남기고둘째pass에서cpu_start/dma_start/size를작성합니다. 두pass사이자료안정성이필요하고임의변경/concurrency를자동보장하는함수는아닙니다.
 * 유효range2개면배열3개와마지막size0을그립니다. 첫count와두번째작성에같은BADskip정책을쓰는이유및calleroutput공간의소유권을확인합니다.
 */
int of_dma_get_range(struct device_node *np, const struct bus_dma_region **map)
{
	struct device_node *node __free(device_node) = of_node_get(np);
	const __be32 *ranges = NULL;
	bool found_dma_ranges = false;
	struct of_range_parser parser;
	struct of_range range;
	struct bus_dma_region *r;
	int len, num_ranges = 0;

	while (node) {
		ranges = of_get_property(node, "dma-ranges", &len);

		/* Ignore empty ranges, they imply no translation required */
		if (ranges && len > 0)
			break;

		/* Once we find 'dma-ranges', then a missing one is an error */
		if (found_dma_ranges && !ranges)
			return -ENODEV;

		found_dma_ranges = true;

		node = of_get_next_dma_parent(node);
