/* 학습 해설
 * OF DMA 최대CPU주소·subtree최소제약
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * 자기dma-ranges의큰CPU끝을계산하고사용가능child재귀결과와작은값을선택합니다. 제약이없으면PHYS_ADDR_MAX입니다. 각단계의range최대와여러master제약의최소를다르게읽고size0/합overflow/변환BAD의모든조건을본문이독립검사한다고설명하지않습니다.
 * child제약0xffff와0x7fff의전체상한0x7fff를계산합니다. inclusive끝start+size-1과재귀subtree범위를주석달아봅니다.
 */
phys_addr_t __init of_dma_get_max_cpu_address(struct device_node *np)
{
	phys_addr_t max_cpu_addr = PHYS_ADDR_MAX;
	struct of_range_parser parser;
	phys_addr_t subtree_max_addr;
	struct device_node *child;
	struct of_range range;
	const __be32 *ranges;
	u64 cpu_end = 0;
	int len;

