/* 학습 해설
 * OF DMA coherence·ancestor정책과기본값
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * DMAparent방향으로node를읽어dma-coherent가있으면true,그다음dma-noncoherent면false입니다. 둘다같은node에있으면첫검사true가우선합니다. 아무설정없으면dma_default_coherent입니다. 속성정책을읽는것과실제cachecoherence측정은별도입니다.
 * node명시/parent상속/기본값의세경로를그립니다. coherent/noncoherent순서와DMAbuffer동기화의실제platform제공자를구별합니다.
 */
bool of_dma_is_coherent(struct device_node *np)
{
	struct device_node *node __free(device_node) = of_node_get(np);

	while (node) {
		if (of_property_read_bool(node, "dma-coherent"))
			return true;

		if (of_property_read_bool(node, "dma-noncoherent"))
			return false;

		node = of_get_next_dma_parent(node);
	}
	return dma_default_coherent;
}
EXPORT_SYMBOL_GPL(of_dma_is_coherent);

/**
 * of_mmio_is_nonposted - Check if device uses non-posted MMIO
 * @np:	device node
 *
 * Returns true if the "nonposted-mmio" property was found for
 * the device's bus.
 *
 * This is currently only enabled on builds that support Apple ARM devices, as
 * an optimization.
 */

/* 학습 해설
 * OF MMIO nonposted·Apple설정과parent속성
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * ARCH_APPLE이꺼지면false이고켜져도parent가없으면false입니다. 정상은parent의nonposted-mmio속성존재를읽습니다. device자신의동명속성을직접보는것과다르며후속resourceflag와ioremap_np선택에연결됩니다.
 * device→parentproperty→MEM_NONPOSTEDflag→mapping선택을그립니다. nonposted접근의실제architecture동작은별도I/O구현을읽어야합니다.
 */
static bool of_mmio_is_nonposted(struct device_node *np)
{
	if (!IS_ENABLED(CONFIG_ARCH_APPLE))
		return false;

	struct device_node *parent __free(device_node) = of_get_parent(np);
	if (!parent)
		return false;

	return of_property_read_bool(parent, "nonposted-mmio");
}

static int __of_address_to_resource(struct device_node *dev, int index, int bar_no,
		struct resource *r)
{
	u64 taddr;
	const __be32	*addrp;
	u64		size;
	unsigned int	flags;
	const char	*name = NULL;

	addrp = __of_get_address(dev, index, bar_no, &size, &flags);
	if (addrp == NULL)
		return -EINVAL;

	/* Get optional "reg-names" property to add a name to a resource */

/* 학습 해설
 * OF 주소resource작성·flags경로와이름
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * entry를얻고선택reg-names를읽습니다. MEM은물리translation,IO는porttranslation,다른flags/BAD는EINVAL입니다. 정상주소뒤resource를0으로채우고nonpostedflag와이름을설정해bounds를검사합니다. 이름은reg-name또는full_name원본pointer입니다.
 * reg-names선택과fallback,주소종류의두경로를그립니다. bounds실패에서도앞flags/name/zeroing이있을수있어전체output불변이라고설명하지않습니다.
 */
static int __of_address_to_resource(struct device_node *dev, int index, int bar_no,
		struct resource *r)
{
	u64 taddr;
	const __be32	*addrp;
	u64		size;
	unsigned int	flags;
	const char	*name = NULL;

	addrp = __of_get_address(dev, index, bar_no, &size, &flags);
	if (addrp == NULL)
		return -EINVAL;

	/* Get optional "reg-names" property to add a name to a resource */
	if (index >= 0)
		of_property_read_string_index(dev, "reg-names",	index, &name);

	if (flags & IORESOURCE_MEM)
		taddr = of_translate_address(dev, addrp);
	else if (flags & IORESOURCE_IO)
		taddr = of_translate_ioport(dev, addrp, size);
	else
		return -EINVAL;

	if (taddr == OF_BAD_ADDR)
		return -EINVAL;

